package com.example.leavemanagement.integration;
import com.example.leavemanagement.audit.persistence.*;import com.example.leavemanagement.policy.application.*;import com.example.leavemanagement.policy.persistence.*;import com.example.leavemanagement.shared.api.DomainException;import com.example.leavemanagement.shared.security.*;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class LeavePolicyAdministrationTest { private final LeaveTypeRepository types=mock(LeaveTypeRepository.class);private final LeavePolicyVersionRepository policies=mock(LeavePolicyVersionRepository.class);private final AuditEventRepository audits=mock(AuditEventRepository.class);private final CurrentActorProvider actors=mock(CurrentActorProvider.class);private final LeavePolicyAdministrationService service=new LeavePolicyAdministrationService(types,policies,audits,actors);private final UUID admin=UUID.randomUUID(); @BeforeEach void setup(){when(actors.require()).thenReturn(new CurrentActor(admin,UUID.randomUUID(),null,Set.of("ADMINISTRATOR"),"Admin"));}
 @Test void createsEffectiveVersionWithConfiguredRules(){var t=LeaveTypeEntity.create(UUID.randomUUID(),"ANNUAL","Annual",null,true);when(types.findById(t.getId())).thenReturn(Optional.of(t));when(policies.findAllByLeaveTypeIdOrderByVersionNumberDesc(t.getId())).thenReturn(List.of());var p=LeavePolicyVersionEntity.create(UUID.randomUUID(),t,1,LocalDate.now(),null,true,true,"EXCLUDE","EXCLUDE",true,5,List.of(6,7),Instant.now());when(policies.save(any())).thenReturn(p);var result=service.createPolicy(t.getId(),new LeavePolicyAdministrationService.PolicyCommand(LocalDate.now(),null,true,true,"EXCLUDE","EXCLUDE",true,5,List.of(6,7),0));assertThat(result.tracksBalance()).isTrue();assertThat(result.weeklyOffDays()).containsExactlyInAnyOrder(6,7);verify(audits).save(any());}
 @Test void parentStaleVersionDoesNotCreatePolicy(){var t=LeaveTypeEntity.create(UUID.randomUUID(),"ANNUAL","Annual",null,true);when(types.findById(t.getId())).thenReturn(Optional.of(t));assertThatThrownBy(()->service.createPolicy(t.getId(),new LeavePolicyAdministrationService.PolicyCommand(LocalDate.now(),null,true,false,"EXCLUDE","INCLUDE",false,0,List.of(),2))).isInstanceOf(DomainException.class).hasMessageContaining("changed");verifyNoInteractions(policies,audits);}
 @Test void rejectsDuplicateWeeklyOffDays(){var t=LeaveTypeEntity.create(UUID.randomUUID(),"ANNUAL","Annual",null,true);when(types.findById(t.getId())).thenReturn(Optional.of(t));assertThatThrownBy(()->service.createPolicy(t.getId(),new LeavePolicyAdministrationService.PolicyCommand(LocalDate.now(),null,true,false,"EXCLUDE","INCLUDE",false,0,List.of(6,6),0))).isInstanceOf(DomainException.class).hasMessageContaining("weeklyOffDays");}
}
